            if (!state.domainState || Object.keys(state.domainState).length === 0 || state.domainState.mv !== 2) {
                state.domainState = MPModel.init(state.gameId || 'local');
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { primary: '', secondary: '', price: 6.5, product: '', channel: '', aw: 21000, co: 9000, ac: 9000, lo: 6000 };
            }
            var self = this;
            setTimeout(function () { try { self._bind(); self._syncControls(); self._render(); } catch (e) {} }, 0);
        }

        _read() {
            var num = function (id) { var el = document.getElementById(id); var v = el ? parseFloat(el.value) : NaN; return isFinite(v) ? v : NaN; };
            var sel = function (id) { var el = document.getElementById(id); return el ? el.value : ''; };
            return { primary: sel('primaryInput'), secondary: sel('secondaryInput'), price: num('priceInput'), product: sel('productInput'), channel: sel('channelInput'),
                aw: num('awInput'), co: num('coInput'), ac: num('acInput'), lo: num('loInput') };
        }

        validateDecisions(decisions) {
            var r = this._read();
            for (var k in r) { if (r.hasOwnProperty(k)) { decisions[k] = r[k]; } }
            var msg = '';
            var tot = (r.aw || 0) + (r.co || 0) + (r.ac || 0) + (r.lo || 0);
            var st = this._state(), ds = st && st.domainState;
            if (!isFinite(r.price) || !isFinite(r.aw) || !isFinite(r.co) || !isFinite(r.ac) || !isFinite(r.lo)) { msg = this._t('err_number'); }
            else if (MPModel.segIndex(r.primary) < 0) { msg = this._t('err_primary'); }
            else if (r.secondary !== 'none' && MPModel.segIndex(r.secondary) < 0) { msg = this._t('err_secondary'); }
            else if (!MPModel.PRODUCT.hasOwnProperty(r.product)) { msg = this._t('err_product'); }
            else if (r.channel !== 'none' && MPModel.chIndex(r.channel) < 0) { msg = this._t('err_channel'); }
            else if (ds && r.channel !== 'none' && ds.channels.indexOf(MPModel.chIndex(r.channel)) >= 0) { msg = this._t('err_channel_active'); }
            else if (tot > MPModel.M.BUDGET) { msg = this._t('err_budget', { t: this._sol(tot), b: this._sol(MPModel.M.BUDGET), x: this._sol(tot - MPModel.M.BUDGET) }); }
            var v = this._el('mpValidation');
            if (v) { v.textContent = msg; }
            return !msg;
        }

        calculateResults(state) {
            // the quarter model lives in MPModel above and in _quarter; this wrapper keeps the importer happy
            return this._quarter(state);
        }

        _quarter(state) {
            var ds = state.domainState;
            var q = state.currentPeriod;
            var row = MPModel.quarter(ds, state.decisions || {}, q);
            var sc = MPModel.score(ds, q);
            var tier = MPModel.tier(sc.composite);
            ds.scoreHistory.push(sc.composite);
            ds.performance = { overallScore: sc.composite, outcome: sc.outcome, process: sc.process, tier: tier,
                share: sc.Sh, profit: sc.P, brand: sc.B, discipline: sc.D };
            ds.performanceTier = tier;
            ds.overallScore = sc.composite;
            return {
                period: q,
                marketShare: row.share, revenue: row.revenue, profit: row.profit, brandEquity: row.beq, price: row.price,
                units: row.units, repeatRate: row.repeat, unitMargin: Math.round(row.unitMargin * 100) / 100,
                overallScore: sc.composite, score: sc.composite, totalScore: sc.composite, composite: sc.composite,
                outcomeScore: sc.outcome, processScore: sc.process
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
        }

        getChartConfig() {
            var self = this;
            var grid = 'rgba(23,43,34,0.08)', ink = '#4b5a52';
            var loc = self._lang() === 'es' ? 'es-PE' : 'en-US';
            var title = function (k) { return { display: true, text: self._t(k), color: '#14231b', font: { size: 13, weight: '600' } }; };
            return {
                shareChart: {
                    type: 'line',
                    data: { labels: [], datasets: [
                        { label: 'Sabores del Valle', data: [], borderColor: '#1f6b47', backgroundColor: '#1f6b47', borderWidth: 3, pointRadius: 4, tension: 0.2 },
                        { label: 'QualiBar', data: [], borderColor: '#5b4f86', backgroundColor: '#5b4f86', borderWidth: 2, pointRadius: 3, tension: 0.2 },
                        { label: 'Fuerza Natural', data: [], borderColor: '#b4441c', backgroundColor: '#b4441c', borderWidth: 2, pointRadius: 3, tension: 0.2 },
                        { label: self._t('ds_path'), data: [], borderColor: '#8a7d55', borderDash: [6, 5], borderWidth: 2, pointRadius: 0, fill: false }
                    ] },
                    options: {
                        responsive: true, maintainAspectRatio: false, animation: false, locale: loc,
                        interaction: { mode: 'index', intersect: false },
                        plugins: { legend: { position: 'bottom', labels: { boxWidth: 12, color: ink } }, title: title('chart_share_title') },
                        scales: {
                            x: { grid: { display: false }, ticks: { color: ink } },
                            y: { beginAtZero: true, suggestedMax: 35, grid: { color: grid }, ticks: { color: ink }, title: { display: true, text: self._t('axis_share'), color: ink } }
                        }
                    }
                },
                beqChart: {
                    type: 'bar',
                    data: { labels: [], datasets: [
                        { label: self._t('p_A'), data: [], backgroundColor: '#8fb9a1' },
                        { label: self._t('p_Q'), data: [], backgroundColor: '#1f6b47' },
                        { label: self._t('p_S'), data: [], backgroundColor: '#c99a3b' },
                        { label: self._t('p_L'), data: [], backgroundColor: '#5b4f86' }
                    ] },
                    options: {
                        responsive: true, maintainAspectRatio: false, animation: false, locale: loc,
                        interaction: { mode: 'index', intersect: false },
                        plugins: { legend: { position: 'bottom', labels: { boxWidth: 12, color: ink } }, title: title('chart_beq_title') },
                        scales: {
                            x: { grid: { display: false }, ticks: { color: ink } },
                            y: { beginAtZero: true, max: 100, grid: { color: grid }, ticks: { color: ink }, title: { display: true, text: self._t('axis_pillar'), color: ink } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var self = this;
            var ds = (state && state.domainState) || {};
            var h = ds.hist || [];
            var M = MPModel.M;
            var labels = [self._t('q_start')].concat(h.map(function (r) { return 'T' + r.q; }));
            if (self._lang() === 'en') { labels = [self._t('q_start')].concat(h.map(function (r) { return 'Q' + r.q; })); }
            var path = [M.SHARE0].concat(h.map(function (r) { return M.PLAN_SHARE[r.q - 1]; }));
            var qb = [22], fn = [31], sv = [M.SHARE0];
            var pa = [M.A0], pq = [M.Q0], ps = [M.S0], pl = [M.L0];
            for (var i = 0; i < h.length; i++) {
                sv.push(h[i].share); qb.push(h[i].qbShare != null ? h[i].qbShare : null); fn.push(h[i].fnShare != null ? h[i].fnShare : null);
                pa.push(Math.round(h[i].A)); pq.push(Math.round(h[i].Q)); ps.push(Math.round(h[i].S)); pl.push(Math.round(h[i].L));
            }
            return {
                shareChart: { labels: labels, datasets: [{ data: sv }, { data: qb }, { data: fn }, { data: path }] },
                beqChart: { labels: labels, datasets: [{ data: pa }, { data: pq }, { data: ps }, { data: pl }] }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.price', label: 'Price', i18nKey: 'col_price', formatter: function (v) { return self._sol(v, 2); } },
                { key: 'results.marketShare', label: 'Share', i18nKey: 'col_share', formatter: function (v) { return self._pct(v, 1); } },
                { key: 'results.units', label: 'Bars sold', i18nKey: 'col_units', formatter: function (v) { return self._num(v); } },
                { key: 'results.unitMargin', label: 'Margin per bar', i18nKey: 'col_margin', formatter: function (v) { return self._sol(v, 2); } },
                { key: 'results.profit', label: 'Profit', i18nKey: 'col_profit', formatter: function (v) { return self._signed(v); } },
                { key: 'results.brandEquity', label: 'Brand equity', i18nKey: 'col_beq' },
                { key: 'results.repeatRate', label: 'Repeat', i18nKey: 'col_repeat', formatter: function (v) { return self._pct(v); } },
                { key: 'results.overallScore', label: 'Score', i18nKey: 'col_score' }
            ];
        }

        getHint() { return null; }
        getPresets() { return null; }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var last = history[history.length - 1] || {};
            var st = this._state();
            var ds = last.domainState || (st && st.domainState) || {};
            var perf = ds.performance || {};
            var s = typeof perf.overallScore === 'number' ? perf.overallScore : 0;
            var tier = perf.tier || MPModel.tier(s);
            var a = this._analyse(ds);
            var lr = last.results || {};
            return {
                totalPeriods: history.length,
                overallScore: s, composite: s, totalScore: s, score: s,
                outcomeScore: perf.outcome, processScore: perf.process,
                performance: tier, performanceKey: tier, performanceLabel: this._t('perf_' + tier),
                insights: a.insights, turningPoint: a.turning,
                finalMarketShare: lr.marketShare, totalProfit: ds.profitTotal, finalBrandEquity: lr.brandEquity, finalPrice: lr.price
            };
        }

        formatCompletionMessage(summary) {
            var st = this._state();
            var ds = (st && st.domainState) || {};
            return this._debriefHTML(ds, summary || {});
        }

        /* ---------- reading a run ---------- */
        _flags(ds) {
            var h = ds.hist || [], f = { bullwhip: 0, bwFrom: 0, bwTo: 0, upward: 0, superAt: 0, awHeavy: 0, switches: [], noLoyalty: 0,
                cheap: 0, secOff: '', unspent: 0, held: true, secUsed: '', secA: 0, secB: 0, lowAc: 0 };
            for (var i = 0; i < h.length; i++) {
                var r = h[i], sp = r.spend || 0;
                if (r.q >= 2 && r.cut >= 0.4 && !f.bullwhip) { f.bullwhip = r.q; f.bwFrom = r.price + r.cut; f.bwTo = r.price; }
                if (r.q >= 2 && r.cut >= 0.4) { f.held = false; }
                if (r.price > 8.0) { f.upward++; }
                if (r.channel === 'super' && r.q <= 2 && !f.superAt) { f.superAt = r.q; }
                if (sp > 0 && (r.aw / sp >= 0.55 || (r.ac + r.lo) / sp < 0.3)) { f.awHeavy++; }
                if (r.switched) { f.switches.push(r.q); }
                if (sp > 0 && r.lo / sp < 0.08) { f.noLoyalty++; }
                if (sp > 0 && r.ac / sp < 0.12) { f.lowAc++; }
                if (r.price < 5.5) { f.cheap++; }
                if (r.secondary !== 'none' && MPModel.SEG[MPModel.segIndex(r.secondary)].fit < 0.75) { f.secOff = r.secondary; }
                f.unspent += r.unspent;
            }
            var last = h[h.length - 1];
            if (last && last.secondary !== 'none') {
                f.secUsed = last.secondary;
                var si = MPModel.segIndex(last.secondary);
                f.secA = MPModel.SEG[si].ss0; f.secB = ds.ss[si];
            }
            return f;
        }

        _analyse(ds) {
            var self = this, h = ds.hist || [], f = this._flags(ds), ins = [], qs = [];
            if (!h.length) { return { insights: [], turning: '', questions: [] }; }
            var last = h[h.length - 1];
            var sh = ds.scoreHistory || [];
            /* turning point: the quarter whose decisions cost the most score, named by its cause */
            var worst = 0, wq = 0;
            for (var i = 1; i < sh.length; i++) { var dl = sh[i] - sh[i - 1]; if (dl < worst) { worst = dl; wq = i + 1; } }
            if (sh.length && sh[0] < 75 && sh[0] - 90 < worst) { worst = sh[0] - 90; wq = 1; }
            var turning;
            if (wq && worst <= -4) {
                var r = h[wq - 1], cause;
                if (r.switched) { cause = this._t('cause_switch', { a: this._seg(h[wq - 2] ? h[wq - 2].primary : r.primary), b: this._seg(r.primary) }); }
                else if (r.q >= 2 && r.cut >= 0.4) { cause = this._t('cause_bullwhip', { a: this._sol(r.price + r.cut, 2), b: this._sol(r.price, 2) }); }
                else if (r.channel === 'super') { cause = this._t('cause_super', { v: this._pct(100 * (r.units ? r.superUnits / r.units : 0), 0) }); }
                else if (r.price > 8.0) { cause = this._t('cause_upward', { p: this._sol(r.price, 2) }); }
                else if (r.spend > 0 && (r.ac + r.lo) / r.spend < 0.3) { cause = this._t('cause_aw', { x: this._pct(100 * (r.ac + r.lo) / r.spend) }); }
                else if (r.price < 5.5) { cause = this._t('cause_cheap', { p: this._sol(r.price, 2) }); }
                else if (r.promo) { cause = this._t('cause_promo', { d: this._pct(100 * r.depth), l: Math.round(r.L) }); }
                else if (r.bundle) { cause = this._t('cause_bundle'); }
                else { cause = this._t('cause_mix', { p: this._signed(r.profit) }); }
                turning = wq > 1 ? this._t('tp_quarter', { q: wq, a: sh[wq - 2], b: sh[wq - 1], cause: cause, c: sh[sh.length - 1] })
                    : this._t('tp_first', { b: sh[0], cause: cause, c: sh[sh.length - 1] });
            } else {
                var lowQ = 1, lowD = 999;
                for (var j = 0; j < sh.length; j++) { var dj = j ? sh[j] - sh[j - 1] : 0; if (j && dj < lowD) { lowD = dj; lowQ = j + 1; } }
                var lo = Math.min.apply(null, sh), hi = Math.max.apply(null, sh);
                if (sh.length < 2) { turning = this._t('tp_one', { c: sh[0] }); }
                else if (lowD >= 0) { turning = this._t('tp_flat', { a: lo, b: hi, c: sh[sh.length - 1], ev: this._t('ev_q' + sh.length) }); }
                else { turning = this._t('tp_steady', { q: lowQ, ev: this._t('ev_q' + lowQ), a: sh[lowQ - 2], b: sh[lowQ - 1], c: sh[sh.length - 1] }); }
            }
            /* mistakes first, each named in its own words */
            if (f.bullwhip) {
                var rb = h[f.bullwhip - 1], rp = h[f.bullwhip - 2];
                ins.push(this._t('ins_bullwhip', { q: f.bullwhip, a: this._sol(f.bwFrom, 2), b: this._sol(f.bwTo, 2), m1: this._sol(rp ? rp.unitMargin : 0, 2), m2: this._sol(rb.unitMargin, 2), l: Math.round(last.L) }));
            }
            if (last.lift > 0 && last.q >= 3) { ins.push(this._t('ins_borrowed', { q: last.q, x: this._pct(100 * last.lift, 0) })); }
            if (f.upward >= 2) { ins.push(this._t('ins_upward', { n: f.upward, s: this._pct(last.share, 1) })); }
            if (f.superAt) {
                var rs = h[f.superAt - 1];
                ins.push(this._t('ins_super', { q: f.superAt, v: this._pct(100 * (rs.units ? rs.superUnits / rs.units : 0), 0), m: this._sol(rs.unitMargin, 2) }));
            }
            if (f.awHeavy >= 2) { ins.push(this._t('ins_aw', { n: f.awHeavy, a: Math.round(last.A), s: this._pct(last.share, 1) })); }
            if (f.switches.length) { ins.push(this._t('ins_switch', { q: f.switches.join(', '), s: Math.round(last.S) })); }
            if (f.noLoyalty >= 2 && f.awHeavy < 2) { ins.push(this._t('ins_noloyalty', { l: Math.round(last.L), r: this._pct(last.repeat) })); }
            if (f.cheap >= 1 && !f.bullwhip) { ins.push(this._t('ins_cheap', { p: this._sol(h[0].price, 2) })); }
            if (f.secOff) { ins.push(this._t('ins_secoff', { s: this._seg(f.secOff) })); }
            /* what went right */
            /* holding the price is the case's discipline only on the mid-price axis; and it keeps the buyers only when
               loyalty is there to keep them, so a weak pillar is named instead of praised */
            if (f.held && last.q >= 3 && last.price >= 5.5 && last.price <= 8.0) {
                ins.push(this._t(Math.round(last.L) >= 50 ? 'ins_held' : 'ins_held_low', { p: this._sol(last.price, 2), d: this._pct(100 * last.depth), l: Math.round(last.L), x: this._num(this._lost(last), 1) }));
            }
            if (f.secUsed && !f.secOff) { ins.push(this._t('ins_secondary', { s: this._seg(f.secUsed), a: this._pct(f.secA, 0), b: this._pct(f.secB, 0) })); }
            if (f.unspent >= 30000) { ins.push(this._t('ins_unspent', { u: this._sol(f.unspent) })); }
            var pi = MPModel.segIndex(last.primary);
            if (pi >= 0) { ins.push(this._t('ins_primary', { s: this._seg(last.primary), a: this._pct(MPModel.SEG[pi].ss0, 0), b: this._pct(ds.ss[pi], 0) })); }
            ins.push(this._t('ins_money', { s: this._pct(last.share, 1), t: this._pct(MPModel.M.TARGET, 0), p: this._sol(ds.profitTotal), b: last.beq }));
            ins = ins.slice(0, 5);
            /* questions for class, from the case's own debrief prompts */
            qs.push(this._t('q_axis'));
            if (f.bullwhip) {
                var r1 = h[f.bullwhip - 2], r2 = h[f.bullwhip - 1];
                qs.push(this._t('q_promo_matched', { q: f.bullwhip, a: this._sol(f.bwFrom, 2), b: this._sol(f.bwTo, 2), m1: this._sol(r1 ? r1.unitMargin : 0, 2), m2: this._sol(r2.unitMargin, 2) }));
            } else {
                var mHeld = last.unitMargin, mMatch = last.unitMargin - (last.price - Math.max(MPModel.M.PMIN, last.price * (1 - (last.depth || 0.2)))) * (1 - (last.fee || 0));
                qs.push(this._t('q_promo_held', { p: this._sol(last.price, 2), m1: this._sol(mHeld, 2), m2: this._sol(mMatch, 2) }));
            }
            if (f.secUsed) { qs.push(this._t('q_secondary', { s: this._seg(f.secUsed), c: this._sol(MPModel.M.SEC_COST * h.filter(function (x) { return x.secondary !== 'none'; }).length) })); }
            else { qs.push(this._t('q_journey')); }
            return { insights: ins, turning: turning, questions: qs };
        }

        /* points of share the rivals' moves took in a quarter: the sum the result panel reports */
        _lost(r) {
            var lost = 0;
            (r.seg || []).forEach(function (x, i) { lost += MPModel.SEG[i].size * x.drain * (x.before / Math.max(6, x.before)); });
            return lost;
        }

        _debriefHTML(ds, summary) {
            var h = ds.hist || [];
            if (!h.length) { return ''; }
            var last = h[h.length - 1], perf = ds.performance || {}, s = perf.overallScore || 0, tier = perf.tier || MPModel.tier(s);
            var a = this._analyse(ds);
            var plan = MPModel.M.PLAN_SHARE[Math.min(last.q, 3) - 1];
            var pathCls = last.share >= plan ? 'ok' : (last.share >= plan - 1.5 ? 'near' : 'no');
            var k = function (label, val) { return '<div class="mp-dkpi"><span>' + label + '</span><strong>' + val + '</strong></div>'; };
            return '<div class="mp-debrief-head">'
                + '<p class="mp-kicker">' + this._t('d_kicker', { q: last.q }) + '</p>'
                + '<h2 class="mp-h2" id="mpDebriefTitle">' + this._t('d_title') + '</h2>'
                + '<p class="mp-debrief-score"><strong>' + s + '</strong><small>/100</small><span class="mp-chip mp-chip-' + tier + '">' + this._t('perf_' + tier) + '</span></p>'
                + '<p class="mp-debrief-sub">' + this._t('d_sub', { o: perf.outcome, p: perf.process }) + '</p></div>'
                + '<div class="mp-dkpis">'
                + k(this._t('d_k_share'), this._pct(last.share, 1)) + k(this._t('d_k_profit'), this._sol(ds.profitTotal))
                + k(this._t('d_k_beq'), last.beq + '/100') + k(this._t('d_k_repeat'), this._pct(last.repeat))
                + k(this._t('d_k_price'), this._sol(last.price, 2)) + k(this._t('d_k_margin'), this._sol(last.unitMargin, 2)) + '</div>'
                + '<p class="mp-rule is-' + pathCls + '">' + ({ ok: '✓ ', near: '≈ ', no: '✗ ' })[pathCls] + this._t('d_path_' + pathCls, { s: this._pct(last.share, 1), p: this._pct(plan, 1), t: this._pct(MPModel.M.TARGET, 0), g: this._num(Math.max(0, MPModel.M.TARGET - last.share), 1) }) + '</p>'
                + '<h3>' + this._t('d_turning') + '</h3><p class="mp-turning">' + a.turning + '</p>'
                + '<h3>' + this._t('d_insights') + '</h3><ul class="mp-insights">' + a.insights.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ul>'
                + '<h3>' + this._t('d_questions') + '</h3><ol class="mp-questions">' + a.questions.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ol>';
        }

        /* ---------- painting ---------- */
        _runOver(st) {
            try { if (window.mySimulation && typeof window.mySimulation.isRunComplete === 'function') { return !!window.mySimulation.isRunComplete(); } } catch (e) {}
            var maxP = (st && st.maxPeriods) || MP_Q;
            if (st && st.currentPeriod > maxP) { return true; }
            var h = (st && st.history) || (window.mySimulation && window.mySimulation.history) || [];
            return h.length >= maxP;
        }

        _bind() {
            if (this._bound) { return; }
            this._bound = true;
            var self = this;
            MP_IDS.forEach(function (id) {
                var el = document.getElementById(id);
                if (!el) { return; }
                var hnd = function () { try { self._paintOutputs(); self._paintHints(); self._paintPreview(); self._paintMap(); var v = self._el('mpValidation'); if (v) { v.textContent = ''; } } catch (e) {} };
                el.addEventListener('input', hnd);
                el.addEventListener('change', hnd);
            });
            document.addEventListener('express:langchanged', function () { try { self._render(); self._paintCharts(); } catch (e) {} });
            var f = window.mySimulation;
            if (f && f.eventBus && typeof f.eventBus.on === 'function') {
                f.eventBus.on('language:changed', function () { try { self._render(); self._paintCharts(); } catch (e) {} });
                f.eventBus.on('period:submitted', function () { try { self._syncControls(); self._render(); } catch (e) {} });
                f.eventBus.on('period:undone', function () { try { self._syncControls(); self._render(); } catch (e) {} });
                f.eventBus.on('state:loaded', function () { try { self._syncControls(); self._render(); } catch (e) {} });
                f.eventBus.on('simulation:complete', function () { try { self._render(); } catch (e) {} });
            }
        }

        /* On resume, undo or a new quarter, the controls show the player's own choices, not the authored defaults:
           the segments and the numbers carry over; product work and a new channel are chosen afresh each quarter. */
        _syncControls() {
            var st = this._state();
            if (!st) { return; }
            var d = st.decisions || {};
            var put = function (id, v) { var el = document.getElementById(id); if (el && v !== undefined && v !== null && v !== '' && isFinite(Number(v))) { el.value = String(v); } };
            ['price', 'aw', 'co', 'ac', 'lo'].forEach(function (k) { put(k + 'Input', d[k]); });
            var played = st.history && st.history.length;
            var ds = st.domainState || {};
            var ps = document.getElementById('primaryInput'), ss = document.getElementById('secondaryInput');
            if (played && ps && ds.primary) { ps.value = ds.primary; }
            if (played && ss && ds.secondary) { ss.value = ds.secondary; }
            var cs = document.getElementById('channelInput');
            if (cs && ds.channels) {
                for (var i = 0; i < cs.options.length; i++) {
                    var ci = MPModel.chIndex(cs.options[i].value);
                    cs.options[i].disabled = ci > 0 && ds.channels.indexOf(ci) >= 0;
                }
                if (cs.value && cs.selectedIndex >= 0 && cs.options[cs.selectedIndex].disabled) { cs.value = ''; }
            }
            this._paintOutputs();
        }

        _render() {
            var st = this._state();
            if (!st || !st.domainState) { return; }
            var ds = st.domainState;
            var over = this._runOver(st);
            var q = over ? (st.history ? st.history.length : MP_Q) : (st.currentPeriod || 1);
            this._paintStatic();
            this._paintSteps(q, over);
            this._paintBriefing(q, over);
            this._paintKpis(ds);
            this._paintScore(ds);
            this._paintResult(ds);
            this._paintOutputs();
            this._paintHints();
            this._paintPreview();
            this._paintMap();
            this._paintChartAlt(ds);
            var form = this._el('mpForm'), deb = this._el('debriefPanel');
            if (over) {
                if (form) { form.hidden = true; }
                if (deb) { deb.innerHTML = this._debriefHTML(ds, this.getPerformanceSummary(st.history)); deb.hidden = false; }
            } else {
                if (form) { form.hidden = false; }
                if (deb) { deb.hidden = true; deb.innerHTML = ''; }
            }
            try { document.documentElement.lang = this._lang(); } catch (e) {}
        }

        _paintStatic() {
            var terms = ['stp', 'axis', 'middle', 'cdj', 'aaker', 'bullwhip', 'fee', 'margin', 'repeat', 'secondary'];
            var html = '';
            for (var i = 0; i < terms.length; i++) { html += '<dt>' + this._t('g_' + terms[i]) + '</dt><dd>' + this._t('g_' + terms[i] + '_d') + '</dd>'; }
            this._set('mpGlossary', html);
            this._set('priceMin', this._sol(MPModel.M.PMIN, 2));
            this._set('priceMax', this._sol(MPModel.M.PMAX, 2));
            this._set('mpBudgetLegend', this._t('group_budget', { b: this._sol(MPModel.M.BUDGET) }));
            var sec = this._el('secondaryInput');
            var lab = document.querySelector('label[for="secondaryInput"]');
            if (lab) { var t = this._t('secondary_label', { c: this._sol(MPModel.M.SEC_COST) }); if (lab.textContent !== t) { lab.textContent = t; } }
        }

        _paintSteps(q, over) {
            var html = '';
            for (var i = 1; i <= MP_Q; i++) {
                var cls = (i < q || (over && i <= q)) ? 'is-done' : (i === q ? 'is-now' : '');
                html += '<li class="' + cls + '"><span>' + this._t('qshort', { q: i }) + '</span></li>';
            }
            this._set('mpSteps', html);
            var c = this._el('mpCal');
            if (c) { c.textContent = over ? this._t('run_complete') : this._t('cal_' + q); }
        }

        _paintBriefing(q, over) {
            var ds = (this._state() || {}).domainState || {};
            this._set('mpTag', over ? this._t('tag_done') : this._t('tag_' + q));
            this._set('mpBriefTitle', over ? this._t('brief_done_title') : this._t('brief_title_' + q));
            this._set('briefingText', over ? this._t('brief_done') : this._t('brief_' + q));
            var mv = '';
            if (!over && q === 2) { mv = this._t('move_2', { p: this._sol(Math.round(MPModel.M.FN_PRICE * 92) / 100, 2) }); }
            if (!over && q === 3) { mv = this._t(ds.escalated ? 'move_3_escalated' : 'move_3'); }
            if (!over && q === 1) { mv = this._t('move_1'); }
            this._set('mpMove', mv);
            var m = this._el('mpMove'); if (m) { m.hidden = !mv; m.className = 'mp-brief-move' + (q >= 2 && !over ? ' is-rival' : ''); }
        }

        _delta(cur, prev, fmt, dec) {
            if (prev == null) { return ''; }
            var d = cur - prev, cls = d > 0.0001 ? 'is-up' : (d < -0.0001 ? 'is-down' : 'is-flat');
            return '<span class="mp-delta ' + cls + '">' + (d > 0.0001 ? '▲ ' : d < -0.0001 ? '▼ ' : '') + fmt(d) + '</span> ' + this._t('vs_prev');
        }

        _paintKpis(ds) {
            var self = this, h = ds.hist || [], last = h[h.length - 1], prev = h[h.length - 2], M = MPModel.M;
            var beq0 = MPModel.beq({ A: M.A0, Q: M.Q0, S: M.S0, L: M.L0 });
            if (!last) {
                this._set('marketShareDisplay', this._pct(M.SHARE0, 1));
                this._set('shareSub', this._t('share_start', { t: this._pct(M.TARGET, 0) }));
                this._set('beqDisplay', beq0 + '<small>/100</small>');
                this._set('beqSub', this._t('beq_sub', { l: M.L0, q: M.Q0 }));
                this._set('profitDisplay', '—');
                this._set('profitSub', this._t('profit_start', { m: this._sol(M.PRICE0 - M.UNIT, 2) }));
                this._set('repeatDisplay', this._pct(Math.round(8 + 0.55 * M.L0)));
                this._set('repeatSub', this._t('repeat_sub'));
                return;
            }
            this._set('marketShareDisplay', this._pct(last.share, 1));
            var plan = M.PLAN_SHARE[last.q - 1];
            this._set('shareSub', this._delta(last.share, prev ? prev.share : M.SHARE0, function (d) { return self._pp(d); }) + ' · ' + this._t('share_plan', { p: this._pct(plan, 1), q: last.q }));
            var sd = this._el('marketShareDisplay'); if (sd) { sd.className = 'mp-kpi-value' + (last.share < plan - 1.5 ? ' is-bad' : ''); }
            this._set('beqDisplay', last.beq + '<small>/100</small>');
            this._set('beqSub', this._delta(last.beq, prev ? prev.beq : beq0, function (d) { return (d > 0 ? '+' : '') + self._num(d); }) + ' · ' + this._t('beq_sub', { l: Math.round(last.L), q: Math.round(last.Q) }));
            this._set('profitDisplay', this._signed(last.profit));
            var pd = this._el('profitDisplay'); if (pd) { pd.className = 'mp-kpi-value' + (last.profit < 0 ? ' is-bad' : ''); }
            this._set('profitSub', this._t('profit_sub', { m: this._sol(last.unitMargin, 2), c: this._sol(ds.profitTotal) }));
            this._set('repeatDisplay', this._pct(last.repeat));
            this._set('repeatSub', this._delta(last.repeat, prev ? prev.repeat : Math.round(8 + 0.55 * M.L0), function (d) { return (d > 0 ? '+' : '') + self._num(d) + ' pp'; }));
        }

        _paintScore(ds) {
            var h = ds.hist || [], last = h[h.length - 1], p = ds.performance || {};
            if (!last) {
                this._set('mpScoreCard', '<p class="mp-score-head">' + this._t('score_title') + '</p><p class="mp-score-empty">' + this._t('score_empty') + '</p>');
                return;
            }
            var tier = p.tier || 'reorient';
            var bar = function (label, v, cls) {
                var pct = Math.round(100 * (v || 0));
                return '<div class="mp-bar"><span>' + label + '</span><span class="mp-bar-track"><span class="mp-bar-fill ' + cls + '" style="width:' + pct + '%"></span></span><span class="mp-bar-val">' + pct + '</span></div>';
            };
            var html = '<p class="mp-score-head">' + this._t('score_title')
                + '<span class="mp-score-num">' + p.overallScore + '<small>/100</small></span>'
                + '<span class="mp-chip mp-chip-' + tier + '">' + this._t('perf_' + tier) + '</span></p>'
                + bar(this._t('bar_share'), p.share, 'is-share') + bar(this._t('bar_profit'), p.profit, 'is-profit')
                + bar(this._t('bar_brand'), p.brand, 'is-brand') + bar(this._t('bar_disc'), p.discipline, 'is-disc')
                + '<p class="mp-score-note">' + this._t('score_note') + '</p>';
            this._set('mpScoreCard', html);
        }

        _paintResult(ds) {
            var self = this, h = ds.hist || [], r = h[h.length - 1];
            if (!r) {
                this._set('mpResultPanel', '<h3 class="mp-h3">' + this._t('res_title_0') + '</h3><p class="mp-result-head">' + this._t('res_empty') + '</p>');
                return;
            }
            var li = [];
            var pi = MPModel.segIndex(r.primary), seg = pi >= 0 ? r.seg[pi] : null;
            li.push(this._t('res_share', { s: this._pct(r.share, 1), d: this._pp(r.share - r.shareBefore), g: this._seg(r.primary), a: this._pct(seg ? seg.before : 0, 0), b: this._pct(seg ? seg.after : 0, 0) }));
            var si = r.secondary && r.secondary !== 'none' ? MPModel.segIndex(r.secondary) : -1, sseg = si >= 0 ? r.seg[si] : null;
            if (sseg) { li.push(this._t('res_sec', { g: this._seg(r.secondary), a: this._pct(sseg.before, 0), b: this._pct(sseg.after, 0) })); }
            var lost = this._lost(r);
            if (r.q === 2) { li.push('<strong>' + this._t('res_q2', { p: this._sol(r.fnPrice, 2), x: this._num(lost, 1) }) + '</strong>'); }
            if (r.q === 3) { li.push('<strong>' + this._t(r.escalated ? 'res_q3_esc' : 'res_q3', { d: this._pct(100 * r.depth), x: this._num(lost, 1), l: Math.round(r.L) }) + '</strong>'); }
            if (r.switched) { li.push('<strong>' + this._t('res_switch', { c: this._sol(MPModel.M.REPOS_COST) }) + '</strong>'); }
            if (r.cut >= 0.4) { li.push('<strong>' + this._t('res_cut', { a: this._sol(r.price + r.cut, 2), b: this._sol(r.price, 2) }) + '</strong>'); }
            if (r.lift > 0) { li.push(this._t('res_lift', { x: this._pct(100 * r.lift, 0) })); }
            if (r.dip > 0) { li.push(this._t('res_dip', { x: this._pct(100 * r.dip, 0) })); }
            li.push(this._t('res_margin', { u: this._num(r.units), p: this._sol(r.price, 2), f: this._pct(100 * r.fee, 0), m: this._sol(r.unitMargin, 2), v: this._signed(r.profit) }));
            if (r.returns > 0) { li.push('<strong>' + this._t('res_returns', { n: this._num(r.returns), w: this._sol(r.writeOff) }) + '</strong>'); }
            var prev = h[h.length - 2] || { A: MPModel.M.A0, Q: MPModel.M.Q0, S: MPModel.M.S0, L: MPModel.M.L0 };
            var arrow = function (a, b) { var d = Math.round(b) - Math.round(a); return Math.round(b) + (d > 0 ? ' (▲' + d + ')' : d < 0 ? ' (▼' + (-d) + ')' : ''); };
            li.push(this._t('res_beq', { b: r.beq, a: arrow(prev.A, r.A), q: arrow(prev.Q, r.Q), s: arrow(prev.S, r.S), l: arrow(prev.L, r.L) }));
            this._set('mpResultPanel', '<h3 class="mp-h3">' + this._t('res_title', { q: r.q }) + '</h3><ul class="mp-why">' + li.map(function (x) { return '<li>' + x + '</li>'; }).join('') + '</ul>');
        }

        _paintOutputs() {
            var r = this._read();
            if (isFinite(r.price)) { this._set('priceOut', this._sol(r.price, 2)); }
            var self = this;
            ['aw', 'co', 'ac', 'lo'].forEach(function (k) { if (isFinite(r[k])) { self._set(k + 'Out', self._sol(r[k])); } });
            var tot = (r.aw || 0) + (r.co || 0) + (r.ac || 0) + (r.lo || 0), B = MPModel.M.BUDGET;
            var seg = function (v, cls) { return '<span class="mp-tot-seg ' + cls + '" style="width:' + Math.max(0, Math.min(100, 100 * v / Math.max(B, tot))) + '%"></span>'; };
            var over = tot > B;
            this._set('mpTotal', '<div class="mp-tot-bar' + (over ? ' is-over' : '') + '" aria-hidden="true">' + seg(r.aw || 0, 'is-aw') + seg(r.co || 0, 'is-co') + seg(r.ac || 0, 'is-ac') + seg(r.lo || 0, 'is-lo') + '</div>'
                + '<p class="mp-tot-text' + (over ? ' is-over' : '') + '">' + this._t(over ? 'tot_over' : 'tot_ok', { t: this._sol(tot), b: this._sol(B), u: this._sol(Math.abs(B - tot)) }) + '</p>');
        }

        _paintHints() {
            var st = this._state(), ds = (st && st.domainState) || {}, r = this._read();
            var pi = MPModel.segIndex(r.primary);
            if (pi >= 0) {
                var S = MPModel.SEG[pi];
                var where = S.ch.map(function (c) { return this._t('chname_' + MPModel.CH[c].key); }, this).join(', ');
                this._set('primaryHint', '<strong>' + this._seg(r.primary) + ':</strong> ' + this._t('seginfo', { z: this._pct(100 * S.size, 0), p: this._sol(S.wtp, 2), w: where, v: this._t('segwhy_' + r.primary) }));
            } else {
                this._set('primaryHint', this._t('seginfo_none'));
            }
            this._set('priceHint', this._t('price_hint', { f: this._sol(ds.fnPrice || MPModel.M.FN_PRICE, 2), q: this._sol(ds.qbPrice || MPModel.M.QB_PRICE, 2), c: this._sol(MPModel.M.UNIT, 2) }));
            var ci = MPModel.chIndex(r.channel);
            if (ci > 0) {
                var who = [];
                MPModel.SEG.forEach(function (s) { if (s.ch.indexOf(ci) >= 0) { who.push(this._t('segshort_' + s.key)); } }, this);
                this._set('channelHint', this._t('ch_info', { f: this._pct(100 * MPModel.CH[ci].fee, 0), w: who.join(', ') }));
            } else {
                var act = (ds.channels || [0]).map(function (c) { return this._t('chname_' + MPModel.CH[c].key); }, this).join(', ');
                this._set('channelHint', this._t('ch_active', { a: act }));
            }
        }

        _paintPreview() {
            var st = this._state();
            if (!st || !st.domainState || this._runOver(st)) { this._set('mpPreview', ''); return; }
            var ds = st.domainState, r = this._read();
            if (!isFinite(r.price)) { return; }
            var d = MPModel.norm(r);
            var chs = ds.channels.slice(), ci = MPModel.chIndex(r.channel);
            if (ci > 0 && chs.indexOf(ci) < 0) { chs.push(ci); }
            var fee = MPModel.feeMix(chs, ds.ss);
            var unitM = d.price * (1 - fee) - MPModel.M.UNIT;
            var o = MPModel.outlay(ds, d);
            var item = function (label, val, warn) { return '<div class="mp-prev-item' + (warn ? ' is-warn' : '') + '"><span>' + label + '</span><strong>' + val + '</strong></div>'; };
            var html = item(this._t('prev_margin'), this._sol(unitM, 2), unitM < 2.2)
                + item(this._t('prev_fee'), this._pct(100 * fee, 0), fee > 0.08)
                + item(this._t('prev_cost'), this._sol(o.total), false)
                + item(this._t('prev_unspent'), this._sol(Math.max(0, MPModel.M.BUDGET - o.mkt)), false)
                + (o.repos ? item(this._t('prev_repos'), this._sol(o.repos), true) : '')
                + (r.secondary && r.secondary === r.primary ? item(this._t('prev_secsame'), this._t('prev_secsame_v'), true) : '');
            this._set('mpPreview', html);
        }

        _paintMap() {
            var st = this._state(), ds = (st && st.domainState) || {}, r = this._read();
            var p = isFinite(r.price) ? r.price : (ds.price || MPModel.M.PRICE0), q = ds.Q != null ? ds.Q : MPModel.M.Q0;
            var W = 420, H = 160, x = function (v) { return 40 + (v - 3.5) / (10.5 - 3.5) * (W - 60); }, y = function (v) { return H - 24 - (v - 25) / (85 - 25) * (H - 40); };
            var fp = ds.fnPrice || MPModel.M.FN_PRICE, qp = ds.qbPrice || MPModel.M.QB_PRICE;
            var dot = function (cx, cy, r0, cls, label, dx, anchor) {
                return '<circle cx="' + cx.toFixed(1) + '" cy="' + cy.toFixed(1) + '" r="' + r0 + '" class="' + cls + '"></circle>'
                    + '<text x="' + (cx + dx).toFixed(1) + '" y="' + (cy + 4).toFixed(1) + '" text-anchor="' + anchor + '" class="mp-map-lbl">' + label + '</text>';
            };
            var svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" width="100%" height="100%" preserveAspectRatio="xMidYMid meet" aria-hidden="true" focusable="false">'
                + '<line x1="40" y1="' + (H - 24) + '" x2="' + (W - 10) + '" y2="' + (H - 24) + '" class="mp-map-axis"></line>'
                + '<line x1="40" y1="8" x2="40" y2="' + (H - 24) + '" class="mp-map-axis"></line>'
                + '<text x="' + (W - 10) + '" y="' + (H - 30) + '" text-anchor="end" class="mp-map-ax">' + this._t('map_x') + ' →</text>'
                + '<text x="46" y="16" class="mp-map-ax">↑ ' + this._t('map_y') + '</text>'
                + '<text x="' + x(4) + '" y="' + (H - 8) + '" text-anchor="middle" class="mp-map-tick">' + this._sol(4) + '</text>'
                + '<text x="' + x(7) + '" y="' + (H - 8) + '" text-anchor="middle" class="mp-map-tick">' + this._sol(7) + '</text>'
                + '<text x="' + x(10) + '" y="' + (H - 8) + '" text-anchor="middle" class="mp-map-tick">' + this._sol(10) + '</text>'
                + dot(x(fp), y(38), 7, 'mp-map-fn', 'Fuerza Natural', 11, 'start')
                + dot(x(qp), y(72), 7, 'mp-map-qb', 'QualiBar', -11, 'end')
                + dot(x(p), y(q), 9, 'mp-map-sv', 'Sabores', 13, 'start')
                + '</svg>';
            this._set('mpMap', svg);
            this._set('mpMapAlt', this._t('map_alt', { p: this._sol(p, 2), q: Math.round(q), f: this._sol(fp, 2), b: this._sol(qp, 2) }));
        }

        _paintChartAlt(ds) {
            var h = ds.hist || [];
            if (!h.length) { this._set('shareChartAlt', this._t('alt_empty')); this._set('beqChartAlt', this._t('alt_empty')); return; }
            var l = h[h.length - 1];
            this._set('shareChartAlt', this._t('alt_share', { a: this._pct(MPModel.M.SHARE0, 1), b: this._pct(l.share, 1), p: this._pct(MPModel.M.PLAN_SHARE[l.q - 1], 1), q: this._pct(l.qbShare, 1), f: this._pct(l.fnShare, 1), n: h.length }));
            this._set('beqChartAlt', this._t('alt_beq', { a: Math.round(l.A), q: Math.round(l.Q), s: Math.round(l.S), l: Math.round(l.L), b: l.beq }));
        }

        _paintCharts() {
            try {
                var f = window.mySimulation;
                if (f && typeof f.updateCharts === 'function') { f.updateCharts(); }
                else if (f && f.uiManager && typeof f.uiManager.updateCharts === 'function') { f.uiManager.updateCharts(f.state); }
            } catch (e) {}
            this._relabelCharts();
        }

        /* Chart.js keeps the titles, legends and axis names it was created with: give them the current language. */
        _relabelCharts() {
            try {
                var f = window.mySimulation, ch = f && f.uiManager && f.uiManager.charts;
                if (!ch) { return; }
                var cfg = this.getChartConfig();
                Object.keys(cfg).forEach(function (id) {
                    var c = ch[id], n = cfg[id];
                    if (!c || !c.options) { return; }
                    if (c.options.plugins && c.options.plugins.title) { c.options.plugins.title.text = n.options.plugins.title.text; }
                    if (c.options.scales && c.options.scales.y && c.options.scales.y.title) { c.options.scales.y.title.text = n.options.scales.y.title.text; }
                    if (c.data && c.data.datasets) { c.data.datasets.forEach(function (d, i) { if (n.data.datasets[i]) { d.label = n.data.datasets[i].label; } }); }
                    c.options.locale = n.options.locale;
                    c.update();
                });
            } catch (e) {}
        }

